const emails = $input.all();
const total = emails.length;
const dateStr = new Date().toLocaleDateString('vi-VN', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'Asia/Ho_Chi_Minh'
});

if (total === 0) {
  return [{ json: { message: `📧 *Báo Cáo Email - ${dateStr}*\n\n✅ Không có email mới!` } }];
}

const list = emails.slice(0, 10).map((item, i) => {
  const from = (item.json.from || 'Unknown').replace(/<[^>]+>/g, '').trim().substring(0, 40);
  const subject = (item.json.subject || '(no subject)').substring(0, 55);
  return `${i+1}. *${subject}*\n   📤 ${from}`;
}).join('\n\n');

const extra = total > 10 ? `\n\n_... và ${total - 10} email khác_` : '';

return [{ json: {
  message: `📧 *Báo Cáo Email Sáng*\n📅 ${dateStr}\n\n📊 Tổng chưa đọc: *${total} email*\n\n${list}${extra}\n\n💡 Mở Gmail để xử lý nhé!`,
  total
}}];
